import wb.RequestJournal;import org.json.*;import java.nio.file.*;
public class RequestJournalProbe {static int n;static void ok(boolean x){if(!x)throw new AssertionError("case "+n);n++;}public static void main(String[] a)throws Exception{Path dir=Files.createTempDirectory("door-journal-test-");Path f=dir.resolve("requests.json");try{RequestJournal j=new RequestJournal(f.toFile());String id=j.begin("副驾关门","test-model","api.example.com",new JSONObject().put("event","door_closed"));JSONObject body=wb.ModelClient.payload(new JSONObject().put("model","test-model").put("persona","test-persona").put("key","must-not-leak"),new JSONObject().put("door","passenger"),"车门关闭");j.payload(id,body);body.put("mutated",true);ok(!j.list().getJSONObject(0).getJSONObject("requestBody").has("mutated"));ok(!j.list().getJSONObject(0).getJSONObject("requestBody").has("key"));ok(j.list().getJSONObject(0).getJSONObject("requestBody").getJSONArray("messages").getJSONObject(1).getString("content").contains("passenger"));j.update(id,"等待播报",200,380,"欢迎回来",new JSONObject().put("total_tokens",12).put("secret_extra","excluded"));ok(j.list().getJSONObject(0).getInt("elapsed_ms")==380);ok(!j.list().getJSONObject(0).getJSONObject("usage").has("secret_extra"));RequestJournal restored=new RequestJournal(f.toFile());ok(restored.list().getJSONObject(0).has("requestBody"));ok(restored.list().getJSONObject(0).getString("status").contains("已中断"));for(int i=0;i<90;i++)restored.begin("门"+i,"m","host",null);ok(restored.list().length()==80);ok(restored.list().getJSONObject(0).getString("source").equals("门89"));ok(!restored.list().getJSONObject(0).has("context"));RequestJournal again=new RequestJournal(f.toFile());ok(again.list().length()==80);again.clear();ok(new RequestJournal(f.toFile()).list().length()==0);System.out.println(n+" persistence/capacity/restart/privacy assertions passed");}finally{Files.deleteIfExists(f);Files.deleteIfExists(dir.resolve("requests.json.tmp"));Files.deleteIfExists(dir);}}}
